package com.aicharacter.v3;
/** Converts real landing/impact energy into body consequences. No random injury events. */
public final class ImpactEngine{private ImpactEngine(){}
 public static void land(WorldState s,String actor,double verticalSpeed,long now){if(s==null||verticalSpeed<=0)return;PhysicsBodyState p="cat".equals(actor)?s.catPhysics:s.girlPhysics;if(p==null)return;double energy=.5*p.massKg*verticalSpeed*verticalSpeed;double tolerance="cat".equals(actor)?85:260;double excess=Math.max(0,energy-tolerance);p.velocityY=0;p.grounded=true;p.falling=false;p.groundReaction=p.massKg*WholeBodyPhysicsEngine.GRAVITY+Math.min(p.massKg*WholeBodyPhysicsEngine.GRAVITY*5,energy*.18);if(excess<=0)return;if("girl".equals(actor)){double pain=Math.min(34,excess/55.0);s.body.pain=Math.min(100,s.body.pain+pain);s.body.health=Math.max(0,s.body.health-Math.min(12,excess/240.0));if(pain>8&& !s.body.hasInjury())s.body.injury="impact strain";s.body.clamp();}else{s.catState.energy=Math.max(0,s.catState.energy-Math.min(18,excess/35.0));}WorldEventBus.publish(s,now,"PHYSICAL_IMPACT","impact_"+actor+"_"+now,actor+" had a physical landing impact.");}
}